"""Generate new typed Rust/Polars/Python wrappers from scripts/api.json.

Run after extract_api.py when updating the pinned upstream release.
"""

import ast
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def generate():
    init = (ROOT / "python/polars_talib/__init__.py").read_text()
    old = {n.name for n in ast.parse(init).body if isinstance(n, ast.FunctionDef)}
    api = json.loads((ROOT / "scripts/api.json").read_text())
    added = [f for f in api if f["name"] not in old]
    py = [
        "# Generated by scripts/generate_indicators.py. Do not edit.",
        "import polars as pl",
        "from polars._typing import IntoExpr",
        "from .utils import register_plugin",
        "from pathlib import Path",
        "lib = Path(__file__).parent",
        "",
    ]
    methods = []
    groups = {}
    structs = {}
    for f in added:
        n = f["name"]
        inputs = f["inputs"]
        params = f["params"]
        outputs = f["outputs"]
        # Match existing band field names.
        for o in outputs:
            if len(outputs) > 1 and o["name"].startswith("real"):
                o["name"] = o["name"][4:]
        groups.setdefault(f["group"], []).append(n)
        if len(outputs) > 1:
            structs[n] = [o["name"] for o in outputs]
        primary = "close" if "close" in inputs else inputs[0]

        def default(i):
            return 'pl.col("' + ("close" if i.startswith("real") else i) + '")'

        ps = [
            f"{p['name']}: {'float' if p['type'] == 'double' else 'int'} = {p['default']!r}"
            for p in params
        ]
        doc = (
            f"{f['description']} ({f['group']}). Outputs: {', '.join(o['name'] for o in outputs)}."
        )
        py += [
            f"def {n}("
            + ", ".join([f"{i}: IntoExpr = {default(i)}" for i in inputs] + ps)
            + ") -> pl.Expr:",
            f'    """{doc}"""',
            "    return register_plugin("
            + f'args=[{", ".join(inputs)}], symbol="{n}", is_elementwise=False, lib=lib, kwargs={{'
            + ", ".join(f'"{p["name"]}": {p["name"]}' for p in params)
            + "})",
            "",
            f"_call_{n} = {n}",  # parameters such as percentile's `percentile` shadow the function
            "",
        ]
        methods += [
            f"    def {n}("
            + ", ".join(
                ["self"] + [f"{i}: IntoExpr = {default(i)}" for i in inputs if i != primary] + ps
            )
            + ") -> pl.Expr:",
            f'        """{doc} The receiver is {primary}."""',
            f"        return _call_{n}("
            + ", ".join(f"{i}=" + ("self._expr" if i == primary else i) for i in inputs)
            + (", " if params else "")
            + ", ".join(f"{p['name']}={p['name']}" for p in params)
            + ")",
            "",
        ]
    py += [
        "__all__ = " + repr([f["name"] for f in added]),
        "GROUPS = " + repr(groups),
        "STRUCTS = " + repr(structs),
        "",
        "class TAExprMixin:",
        '    """Namespace methods for indicators added after TA-Lib 0.4.0."""',
        "",
        "    _expr: pl.Expr",
        "",
    ]
    py += methods
    for path, lines in [
        ("python/polars_talib/_generated.py", py),
    ]:
        (ROOT / path).write_text("\n".join(lines) + "\n")
    from generate_usage_examples import generate as generate_examples
    generate_examples()
    integer_params = {
        f["name"]: [p["name"] for p in f["params"] if p["type"] != "double"]
        for f in api
        if any(p["type"] != "double" for p in f["params"])
    }
    real_params = {f["name"]: [p["name"] for p in f["params"] if p["type"] == "double"]
                   for f in api if any(p["type"] == "double" for p in f["params"])}
    (ROOT / "python/polars_talib/_param_types.py").write_text(
        "# Generated by scripts/generate_indicators.py. Do not edit.\nINTEGER_PARAMETERS = "
        + json.dumps(integer_params, indent=4)
        + "\nREAL_PARAMETERS = " + json.dumps(real_params, indent=4)
        + "\n"
    )
    catalog = [
        "# Indicator catalog",
        "",
        "Generated from the pinned TA-Lib 0.8.1 API. All 201 functions are available as",
        "`polars_talib.<name>` and `pl.col(...).ta.<name>`. Use `inspect.signature`",
        "for Python argument order and `get_functions_output_struct()` for Struct fields.",
        "",
    ]
    for group in dict.fromkeys(f["group"] for f in api):
        catalog += ["## " + group, "", "| Function | Description |", "| --- | --- |"]
        catalog += [f"| `{f['name']}` | {f['description']} |" for f in api if f["group"] == group]
        catalog.append("")
    (ROOT / "docs/indicators.md").write_text("\n".join(catalog) + "\n")
    import subprocess

    subprocess.run(
        ["python3", str(ROOT / "scripts/generate_native.py")],
        check=True,
    )
    print(f"Generated {len(added)} new indicators")


if __name__ == "__main__":
    generate()
